DO $x$ BEGIN IF (SELECT qual FROM pg_policies WHERE schemaname='public' AND tablename='customer_loyalty_settings' AND policyname='Studio members manage loyalty settings') IS DISTINCT FROM 'is_studio_member(( SELECT auth.uid() AS uid), studio_id)' THEN RAISE EXCEPTION 'loyalty_policy_drift'; END IF; EXECUTE 'DROP POLICY "Studio members manage loyalty settings" ON public.customer_loyalty_settings'; EXECUTE $p$CREATE POLICY "Studio members manage loyalty settings" ON public.customer_loyalty_settings FOR ALL TO authenticated USING (public.is_studio_member(auth.uid(),studio_id) AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.studio_id=customer_loyalty_settings.studio_id AND r.role IN ('saas_owner','studio_owner','manager'))) WITH CHECK (public.is_studio_member(auth.uid(),studio_id) AND EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.studio_id=customer_loyalty_settings.studio_id AND r.role IN ('saas_owner','studio_owner','manager')))$p$; END $x$;
